cases.new:
| storagePush_unfold_leftCallReceiver {m : Modality} {Γ : Ctx} {f : Name} {x : Ctx}
    {args : Args C Γ x} {r : Var} {x_1 : Ty} {x_2 : Ctx}
    {body : Prog C ([.alias (.array x_1)] ++ x) x_2}
    {hd : ((none : Option (Src C Γ x_1)).isSome || x_1.defaultOkS) = true} :
    Taclet C k m (.callReceiver f args r body (.push none hd))
      (.unfold
        (.cons (.call f args (.storage (.array x_1) r) body)
          (.cons (.call f (args.wk (.drop .refl)) (.storage (.array x_1) r) body)
            (.cons (.push (.alias .here) none hd) .nil)))
        (.push (.push .refl)))

